import numpy as np

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_stock = 104.80540941891769  # OPT_PARAM: {"initial": 104.80540941891769, "min": 100.0, "max": 300.0, "type": "float"}
    demand_response = 0.14070271259726402  # OPT_PARAM: {"initial": 0.14070271259726402, "min": 0.1, "max": 1.5, "type": "float"}
    pipeline_adjustment = 0.3976243733442719  # OPT_PARAM: {"initial": 0.3976243733442719, "min": 0.1, "max": 0.5, "type": "float"}

    inventory_position = on_hand_inventory + np.sum(pipeline_orders)
    demand_component = demand_response * last_demand
    order_amount = max(0.0, base_stock + demand_component - pipeline_adjustment * inventory_position)
    return order_amount
